schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "faion://govtech-foia-ba-pack/output.schema.json",
  "title": "GovTech FOIA / records-retention BA pack",
  "type": "object",
  "required": [
    "system_name", "jurisdiction", "access_request_clock_working_days",
    "record_classes", "data_stores", "exemption_map", "staff_channels",
    "accessibility_audit", "clause_review_log", "public_notice",
    "records_officer", "access_request_officer", "schedule_approved_on",
    "launch_date", "blocking_findings"
  ],
  "additionalProperties": false,
  "definitions": {
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "date": {"type": "string", "format": "date", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
    "clause_entries": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["clause_id", "design_decision", "status", "evidence"],
        "additionalProperties": false,
        "properties": {
          "clause_id": {"type": "string", "minLength": 2},
          "design_decision": {"type": "string", "minLength": 10},
          "status": {"type": "string", "enum": ["met", "open", "waived"]},
          "waived_by": {"$ref": "#/definitions/handle"},
          "evidence": {"type": "string", "format": "uri"}
        },
        "if": {"properties": {"status": {"const": "waived"}}},
        "then": {"required": ["waived_by"]}
      }
    }
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "system_name": {"type": "string", "minLength": 3},
    "jurisdiction": {"type": "string", "enum": ["us-federal", "us-state", "uk", "eu", "ca-federal", "ca-provincial"]},
    "access_request_clock_working_days": {"type": "integer", "minimum": 1, "maximum": 60},
    "record_classes": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["name", "retention_period", "disposition", "schedule_item"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 3},
          "retention_period": {"type": "string", "pattern": "^P(\\d+Y)?(\\d+M)?(\\d+D)?$", "description": "ISO-8601 duration, e.g. P7Y; never open-ended"},
          "disposition": {"type": "string", "enum": ["destroy", "transfer-to-archives"]},
          "schedule_item": {"type": "string", "minLength": 5, "description": "NARA GRS item, agency schedule, PRA 1958 body schedule, state or provincial archives item"},
          "stores": {"type": "array", "items": {"type": "string"}}
        }
      }
    },
    "data_stores": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["name", "export_path", "export_lead_time_working_days"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 2},
          "export_path": {
            "type": "object",
            "required": ["tool", "query", "owner"],
            "additionalProperties": false,
            "properties": {
              "tool": {"type": "string", "minLength": 2},
              "query": {"type": "string", "minLength": 2},
              "owner": {"$ref": "#/definitions/handle"}
            }
          },
          "export_lead_time_working_days": {"type": "integer", "minimum": 0},
          "notes": {"type": "string"}
        }
      }
    },
    "exemption_map": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["field", "category", "statutory_basis", "redaction"],
        "additionalProperties": false,
        "properties": {
          "field": {"type": "string", "pattern": "^[A-Za-z0-9_.-]+\\.[A-Za-z0-9_.-]+$", "description": "store.field"},
          "category": {"type": "string", "enum": ["personal-privacy", "law-enforcement", "deliberative", "commercial-confidentiality", "security", "other-statutory"]},
          "statutory_basis": {"type": "string", "minLength": 5, "description": "e.g. 5 U.S.C. §552(b)(6); UK FOIA 2000 s.40"},
          "redaction": {"type": "string", "enum": ["field-driven", "structural-split-required", "manual-review"]},
          "manual_review_cost_estimate": {"type": "string", "minLength": 5}
        },
        "if": {"properties": {"redaction": {"const": "manual-review"}}},
        "then": {"required": ["manual_review_cost_estimate"]}
      }
    },
    "staff_channels": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["channel", "capture_mechanism", "auto_delete"],
        "additionalProperties": false,
        "properties": {
          "channel": {"type": "string", "minLength": 2},
          "capture_mechanism": {"type": "string", "minLength": 5},
          "auto_delete": {"type": "boolean"},
          "non_official_copy_within_days": {"type": "integer", "minimum": 1, "maximum": 20, "description": "44 U.S.C. §2911 for us-federal"}
        }
      }
    },
    "accessibility_audit": {
      "type": "object",
      "required": ["wcag_version", "level", "flows", "launch_gate", "accessibility_statement_required"],
      "additionalProperties": false,
      "properties": {
        "wcag_version": {"type": "string", "enum": ["2.1", "2.2"]},
        "level": {"type": "string", "const": "AA"},
        "standard_reference": {"type": "string", "enum": ["section-508", "en-301-549", "uk-psbar-2018", "aoda", "other"]},
        "flows": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["flow", "automated_tool", "manual_tests", "remediation_owner"],
            "additionalProperties": false,
            "properties": {
              "flow": {"type": "string", "minLength": 3},
              "automated_tool": {"type": "string", "minLength": 2},
              "manual_tests": {
                "type": "array",
                "minItems": 3,
                "uniqueItems": true,
                "items": {"type": "string", "enum": ["screen-reader", "keyboard-only", "zoom-200"]}
              },
              "remediation_owner": {"$ref": "#/definitions/handle"}
            }
          }
        },
        "launch_gate": {"type": "string", "const": "no-critical-or-serious-failure"},
        "accessibility_statement_required": {"type": "boolean"},
        "accessibility_statement_url": {"type": "string", "format": "uri"}
      },
      "if": {"properties": {"accessibility_statement_required": {"const": true}}},
      "then": {"required": ["accessibility_statement_url"]}
    },
    "clause_review_log": {
      "type": "object",
      "required": ["data_residency", "security_authorisation", "source_code_escrow_and_ip", "open_source_licence", "subcontractor_flow_down", "accessibility_warranty", "records_transfer_on_termination"],
      "properties": {
        "data_residency": {"$ref": "#/definitions/clause_entries"},
        "security_authorisation": {"$ref": "#/definitions/clause_entries"},
        "source_code_escrow_and_ip": {"$ref": "#/definitions/clause_entries"},
        "open_source_licence": {"$ref": "#/definitions/clause_entries"},
        "subcontractor_flow_down": {"$ref": "#/definitions/clause_entries"},
        "accessibility_warranty": {"$ref": "#/definitions/clause_entries"},
        "records_transfer_on_termination": {"$ref": "#/definitions/clause_entries"}
      },
      "additionalProperties": {"$ref": "#/definitions/clause_entries"}
    },
    "public_notice": {
      "type": "object",
      "required": ["assessed", "required"],
      "additionalProperties": false,
      "properties": {
        "assessed": {"type": "boolean", "const": true},
        "required": {"type": "boolean"},
        "regime": {"type": "string", "enum": ["pra", "state-apa", "uk-consultation", "eu-consultation", "other"]},
        "buffer_days": {"type": "integer", "minimum": 90},
        "notices_filed": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["notice", "date"],
            "additionalProperties": false,
            "properties": {
              "notice": {"type": "string", "enum": ["60-day-federal-register", "30-day-federal-register", "omb-submission", "consultation-open", "consultation-close", "other"]},
              "date": {"$ref": "#/definitions/date"}
            }
          }
        },
        "omb_control_number": {"type": "string", "pattern": "^\\d{4}-\\d{4}$"}
      },
      "if": {"properties": {"required": {"const": true}}},
      "then": {"required": ["regime", "buffer_days", "notices_filed"]}
    },
    "records_officer": {"$ref": "#/definitions/handle"},
    "access_request_officer": {"$ref": "#/definitions/handle"},
    "schedule_approved_on": {"$ref": "#/definitions/date"},
    "launch_date": {"$ref": "#/definitions/date"},
    "blocking_findings": {"type": "array", "items": {"type": "string", "minLength": 10}}
  },
  "allOf": [
    {
      "if": {"properties": {"jurisdiction": {"enum": ["us-federal", "uk"]}}},
      "then": {
        "properties": {
          "access_request_clock_working_days": {"const": 20},
          "data_stores": {"items": {"properties": {"export_lead_time_working_days": {"maximum": 20}}}}
        }
      }
    }
  ]
}

output-contract.example:
{
  "system_name": "State benefits intake portal",
  "jurisdiction": "us-state",
  "access_request_clock_working_days": 10,
  "record_classes": [
    {"name": "citizen benefit applications", "retention_period": "P7Y", "disposition": "destroy", "schedule_item": "State Archives GRS 4-100 item 12", "stores": ["postgres.applications", "s3.uploads"]},
    {"name": "caseworker notes", "retention_period": "P7Y", "disposition": "destroy", "schedule_item": "State Archives GRS 4-100 item 14", "stores": ["postgres.case_notes"]},
    {"name": "audit logs", "retention_period": "P3Y", "disposition": "destroy", "schedule_item": "State Archives GRS 1-200 item 3", "stores": ["cloudwatch.audit"]},
    {"name": "program policy decisions", "retention_period": "P10Y", "disposition": "transfer-to-archives", "schedule_item": "State Archives GRS 2-050 item 1", "stores": ["sharepoint.policy"]}
  ],
  "data_stores": [
    {"name": "postgres.applications", "export_path": {"tool": "pg_dump + redaction script", "query": "SELECT * FROM applications WHERE applicant_id = ANY($1)", "owner": "dba:marta"}, "export_lead_time_working_days": 2},
    {"name": "postgres.case_notes", "export_path": {"tool": "records-export CLI", "query": "records-export notes --case", "owner": "dba:marta"}, "export_lead_time_working_days": 2},
    {"name": "s3.uploads", "export_path": {"tool": "aws s3 sync by applicant prefix", "query": "s3://intake-uploads/<applicant_id>/", "owner": "sre:dmitri"}, "export_lead_time_working_days": 1},
    {"name": "cloudwatch.audit", "export_path": {"tool": "CloudWatch Logs Insights", "query": "fields @timestamp, actor, action | filter subject_id = <id>", "owner": "sre:dmitri"}, "export_lead_time_working_days": 3},
    {"name": "sharepoint.policy", "export_path": {"tool": "SharePoint eDiscovery", "query": "site:policy-decisions", "owner": "records:jlee"}, "export_lead_time_working_days": 5}
  ],
  "exemption_map": [
    {"field": "postgres.applications.ssn", "category": "personal-privacy", "statutory_basis": "State Public Records Act s.6254(c); 5 U.S.C. §552(b)(6) analogue", "redaction": "field-driven"},
    {"field": "postgres.applications.bank_account", "category": "personal-privacy", "statutory_basis": "State Public Records Act s.6254(c)", "redaction": "field-driven"},
    {"field": "postgres.case_notes.fraud_referral_detail", "category": "law-enforcement", "statutory_basis": "State Public Records Act s.6254(f)", "redaction": "structural-split-required"},
    {"field": "postgres.case_notes.body", "category": "personal-privacy", "statutory_basis": "State Public Records Act s.6254(c)", "redaction": "manual-review", "manual_review_cost_estimate": "about 4 minutes per note; 600 notes per request average = 40 reviewer hours"}
  ],
  "staff_channels": [
    {"channel": "agency email (Exchange)", "capture_mechanism": "journaling to records archive", "auto_delete": false},
    {"channel": "Teams caseworker chat", "capture_mechanism": "Purview retention policy, 7 years, auto-delete disabled", "auto_delete": false},
    {"channel": "vendor ticket tool (Zendesk)", "capture_mechanism": "nightly export to postgres.case_notes via API", "auto_delete": false}
  ],
  "accessibility_audit": {
    "wcag_version": "2.1",
    "level": "AA",
    "standard_reference": "section-508",
    "flows": [
      {"flow": "apply for benefits", "automated_tool": "axe-core in CI", "manual_tests": ["screen-reader", "keyboard-only", "zoom-200"], "remediation_owner": "fe:priya"},
      {"flow": "upload supporting documents", "automated_tool": "axe-core in CI", "manual_tests": ["screen-reader", "keyboard-only", "zoom-200"], "remediation_owner": "fe:priya"},
      {"flow": "check application status", "automated_tool": "axe-core in CI", "manual_tests": ["screen-reader", "keyboard-only", "zoom-200"], "remediation_owner": "fe:priya"}
    ],
    "launch_gate": "no-critical-or-serious-failure",
    "accessibility_statement_required": true,
    "accessibility_statement_url": "https://benefits.example.gov/accessibility"
  },
  "clause_review_log": {
    "data_residency": [{"clause_id": "C-4.2", "design_decision": "All stores in us-west-2 and us-east-1 only; no cross-border replication", "status": "met", "evidence": "https://git.example.gov/intake/infra/pull/88"}],
    "security_authorisation": [{"clause_id": "C-7.1", "design_decision": "StateRAMP Moderate authorisation for the hosting vendor before go-live", "status": "open", "evidence": "https://tickets.example.gov/SEC-311"}],
    "source_code_escrow_and_ip": [{"clause_id": "C-12", "design_decision": "State owns the code; repository mirrored to the state GitLab weekly", "status": "met", "evidence": "https://git.example.gov/intake/mirror"}],
    "open_source_licence": [{"clause_id": "C-12.3", "design_decision": "No AGPL dependencies; SBOM scanned in CI", "status": "met", "evidence": "https://git.example.gov/intake/app/-/jobs/4410"}],
    "subcontractor_flow_down": [{"clause_id": "C-15", "design_decision": "Identity-proofing subcontractor signed the same residency and security terms", "status": "met", "evidence": "https://contracts.example.gov/idp-flowdown.pdf"}],
    "accessibility_warranty": [{"clause_id": "C-9", "design_decision": "WCAG 2.1 AA warranted; audit report attached to acceptance", "status": "met", "evidence": "https://tickets.example.gov/A11Y-20"}],
    "records_transfer_on_termination": [{"clause_id": "C-21", "design_decision": "Records exported as CSV plus PDF/A with schedule metadata within 30 days of termination", "status": "waived", "waived_by": "procurement:hwong", "evidence": "https://contracts.example.gov/waiver-c21.pdf"}]
  },
  "public_notice": {
    "assessed": true,
    "required": true,
    "regime": "state-apa",
    "buffer_days": 120,
    "notices_filed": [
      {"notice": "consultation-open", "date": "2026-03-02"},
      {"notice": "consultation-close", "date": "2026-04-16"}
    ]
  },
  "records_officer": "records:jlee",
  "access_request_officer": "pra-officer:tnguyen",
  "schedule_approved_on": "2026-02-20",
  "launch_date": "2026-07-01",
  "blocking_findings": [
    "clause C-7.1 security_authorisation is open: StateRAMP Moderate letter not yet issued for the hosting vendor"
  ]
}

{
  "system_name": "Federal grant application portal",
  "jurisdiction": "us-federal",
  "access_request_clock_working_days": 20,
  "record_classes": [
    {"name": "grant applications", "retention_period": "P7Y", "disposition": "retain indefinitely", "schedule_item": "NARA GRS 1.2 item 020"}
  ],
  "data_stores": [
    {"name": "kafka.intake-events", "export_path": {"tool": "ask engineering", "query": "custom consumer, not written", "owner": "eng:platform"}, "export_lead_time_working_days": 45}
  ],
  "exemption_map": [
    {"field": "postgres.applications.notes", "category": "personal-privacy", "statutory_basis": "5 U.S.C. §552(b)(6)", "redaction": "manual-review"}
  ],
  "staff_channels": [
    {"channel": "Slack #grants-review", "capture_mechanism": "", "auto_delete": true}
  ],
  "accessibility_audit": {
    "wcag_version": "2.1",
    "level": "A",
    "flows": [
      {"flow": "submit application", "automated_tool": "axe-core", "manual_tests": ["keyboard-only"], "remediation_owner": "fe:priya"}
    ],
    "launch_gate": "post-launch-review",
    "accessibility_statement_required": true
  },
  "clause_review_log": {
    "data_residency": [{"clause_id": "H.4", "design_decision": "US regions only", "status": "met", "evidence": "https://git.example.gov/grants/infra/pull/3"}]
  },
  "public_notice": {
    "assessed": true,
    "required": true,
    "regime": "pra",
    "buffer_days": 30,
    "notices_filed": []
  },
  "records_officer": "records:jlee",
  "access_request_officer": "foia:delegate",
  "schedule_approved_on": "2026-02-20",
  "launch_date": "2026-05-01",
  "blocking_findings": []
}
